style.css:
@-moz-document domain("netflix.com") {
html, body {
    background: url("https://i.pinimg.com/originals/07/4a/61/074a61bd2c3b5c16f39eb6e32cb5a184.jpg") no-repeat center center fixed !important;
    background-size: cover !important;
  }

  /* Fondos oscuros translúcidos para que el texto sea legible */
  .our-story-card, .billboard-row, .previewModal--player-container, 
  .title-card, .lolomoRow, .lolomo, .jawBoneContainer {
    background-color: rgba(0, 0, 0, 0.6) !important;
  }

  /* Cambia el color del texto */
  * {
    color: #e0e0f0 !important;
  }

  /* Elimina sombras fuertes de elementos */
  .title-card .boxart, .previewModal--player-container {
    box-shadow: none !important;
  }
}
